@page "/settings"
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="@(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                    @section.Value
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (_loading)
        {
            <p>Loading...</p>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast @(_toastIsError ? "toast-error" : "toast-success")">
                @_toastMessage
            </div>
        }
    </main>
</div>

@code {
    private readonly Dictionary<string, string> _sections = new()
    {
        ["profile"] = "Profile",
        ["notifications"] = "Notifications",
        ["security"] = "Security",
        ["appearance"] = "Appearance"
    };

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Profile
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    // Notifications
    private NotificationPrefs? _notificationPrefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelMuteState> _channels = new();

    // Security
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private string? _sessionToRevoke;
    private bool _showRevokeConfirmation;

    // Appearance
    private AppearanceSettings? _appearanceSettings;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] AvailableLanguages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _savedProfile = profileTask.Result;
        ApplyProfile(_savedProfile);

        _notificationPrefs = notifTask.Result;
        ApplyNotificationPrefs(_notificationPrefs);

        _securitySettings = securityTask.Result;
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        _appearanceSettings = appearanceTask.Result;
        ApplyAppearance(_appearanceSettings);
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _avatarUrl = profile.AvatarUrl;
    }

    private void ApplyNotificationPrefs(NotificationPrefs prefs)
    {
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _channels = prefs.MutedChannels
            .Select(c => new ChannelMuteState(c, true))
            .ToList();
    }

    private void ApplyAppearance(AppearanceSettings settings)
    {
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
    }

    // --- Profile ---

    private RenderFragment RenderProfile() => __builder =>
    {
        <h2>Profile</h2>

        <div class="form-group">
            <label for="avatar-preview">Avatar</label>
            <div class="avatar-preview" id="avatar-preview">
                @if (!string.IsNullOrEmpty(_avatarUrl))
                {
                    <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
            </div>
            <span class="avatar-url-display">@_avatarUrl</span>
        </div>

        <div class="form-group">
            <label for="display-name">Display Name</label>
            <input id="display-name" type="text" @bind="_displayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio" rows="4"></textarea>
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    };

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully.");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // --- Notifications ---

    private RenderFragment RenderNotifications() => __builder =>
    {
        <h2>Notifications</h2>

        <div class="form-group toggle-group">
            <label>
                <input type="checkbox" @bind="_emailNotifications" />
                <span>Email Notifications</span>
            </label>
        </div>

        <div class="form-group toggle-group">
            <label>
                <input type="checkbox" @bind="_pushNotifications" />
                <span>Push Notifications</span>
            </label>
        </div>

        <div class="form-group toggle-group">
            <label>
                <input type="checkbox" @bind="_weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        @if (_channels.Any())
        {
            <ul class="channel-list">
                @foreach (var channel in _channels)
                {
                    <li>
                        <label>
                            <input type="checkbox" @bind="channel.IsMuted" />
                            <span>@channel.Name</span>
                        </label>
                    </li>
                }
            </ul>
        }
        else
        {
            <p class="text-muted">No channels configured.</p>
        }

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    };

    private async Task SaveNotifications()
    {
        var mutedChannels = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
        ShowToast("Notification preferences saved.");
    }

    // --- Security ---

    private RenderFragment RenderSecurity() => __builder =>
    {
        <h2>Security</h2>

        <div class="panel">
            <div class="panel-header" @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                <h3>Change Password</h3>
                <span class="expand-icon">@(_changePasswordExpanded ? "▾" : "▸")</span>
            </div>
            @if (_changePasswordExpanded)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="current-password">Current Password</label>
                        <input id="current-password" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="new-password">New Password</label>
                        <input id="new-password" type="password" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirm-password">Confirm Password</label>
                        <input id="confirm-password" type="password" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                </div>
            }
        </div>

        <div class="form-group toggle-group">
            <label>
                <input type="checkbox" @bind="_twoFactorEnabled" />
                <span>Two-Factor Authentication</span>
                <span class="status-indicator @(_twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </label>
        </div>

        <h3>Active Sessions</h3>
        @if (_securitySettings?.Sessions.Any() == true)
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _securitySettings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != _securitySettings.Sessions.First())
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session.Id)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="text-muted">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }

        @if (_showRevokeConfirmation)
        {
            <div class="modal-overlay">
                <div class="modal-dialog">
                    <p>Are you sure you want to revoke this session?</p>
                    <div class="button-group">
                        <button class="btn btn-danger" @onclick="RevokeSession">Yes, Revoke</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    };

    private async Task ChangePassword()
    {
        if (_newPassword != _confirmPassword)
        {
            ShowToast("Passwords do not match.", isError: true);
            return;
        }

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("New password cannot be empty.", isError: true);
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        ShowToast("Password updated successfully.");
    }

    private void ConfirmRevokeSession(string sessionId)
    {
        _sessionToRevoke = sessionId;
        _showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeConfirmation = false;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _sessionToRevoke = null;
            _showRevokeConfirmation = false;
            ShowToast("Session revoked.");
        }
    }

    // --- Appearance ---

    private RenderFragment RenderAppearance() => __builder =>
    {
        <h2>Appearance</h2>

        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <label class="radio-label">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label>Font Size</label>
            <div class="radio-group">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <div class="form-group">
            <label for="language-select">Language</label>
            <select id="language-select" @bind="_language">
                @foreach (var lang in AvailableLanguages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="form-group toggle-group">
            <label>
                <input type="checkbox" @bind="_compactMode" />
                <span>Compact Mode</span>
            </label>
        </div>

        <div class="preview-area" style="@GetPreviewStyle()">
            <h4>Live Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p>The quick brown fox jumps over the lazy dog.</p>
        </div>

        <div class="button-group">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    };

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color: #1e1e1e; color: #e0e0e0;",
            "Light" => "background-color: #ffffff; color: #1a1a1a;",
            _ => "background-color: #f5f5f5; color: #333333;"
        };

        var font = _fontSize switch
        {
            "Small" => "font-size: 0.85rem;",
            "Large" => "font-size: 1.25rem;",
            _ => "font-size: 1rem;"
        };

        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1.5rem;";

        return $"{bg} {font} {padding} border-radius: 8px; border: 1px solid #ddd; margin-bottom: 1rem;";
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
        ShowToast("Appearance settings saved.");
    }

    // --- Helpers ---

    private async void ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private class ChannelMuteState
    {
        public string Name { get; set; }
        public bool IsMuted { get; set; }

        public ChannelMuteState(string name, bool isMuted)
        {
            Name = name;
            IsMuted = isMuted;
        }
    }
}

