    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
}

.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
    border-right: 1px solid #e0e0e0;
}

.settings-nav li {
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    border-radius: 6px 0 0 6px;
    margin-bottom: 0.25rem;
    transition: background-color 0.15s;
}

.settings-nav li:hover {
    background-color: #f0f0f0;
}

.settings-nav li.active {
    background-color: #0d6efd;
    color: #fff;
    font-weight: 600;
}

.settings-content {
    flex: 1;
    min-width: 0;
    position: relative;
}

