    font-size: 0.85rem;
}

/* Avatar */
.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #ddd;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 0.5rem;
    background-color: #f5f5f5;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 0.75rem;
    color: #999;
}

.avatar-url-display {
    font-size: 0.8rem;
    color: #666;
    word-break: break-all;
}

/* Channels */
.channel-list {
    list-style: none;
    padding: 0;
}

.channel-list li {
    margin-bottom: 0.5rem;
}

.channel-list label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Panel (expandable) */
.panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    cursor: pointer;
    user-select: none;
}

.panel-header h3 {
    margin: 0;
    font-size: 1rem;
