    border-radius: 12px;
    margin-left: 0.5rem;
}

.status-enabled {
    background-color: #d4edda;
    color: #155724;
}

.status-disabled {
    background-color: #f8d7da;
    color: #721c24;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 1rem;
}

.sessions-table th,
.sessions-table td {
    text-align: left;
