    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
}

.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
    border-right: 1px solid #e0e0e0;
}

.settings-nav li {
    padding: 0.75rem 1.25rem;
    cursor: pointer;
    border-radius: 6px 0 0 6px;
    margin-bottom: 0.25rem;
    transition: background-color 0.15s;
}

.settings-nav li:hover {
    background-color: #f0f0f0;
}

.settings-nav li.active {
    background-color: #0d6efd;
    color: #fff;
    font-weight: 600;
}

.settings-content {
    flex: 1;
    min-width: 0;
    position: relative;
}

.settings-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #e0e0e0;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 1rem;
}

.form-group textarea {
    resize: vertical;
}

/* Toggle groups */
.toggle-group label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-weight: normal;
}

.toggle-group input[type="checkbox"] {
    width: 18px;
    height: 18px;
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: opacity 0.15s;
}

.btn:hover {
    opacity: 0.85;
}

.btn-primary {
    background-color: #0d6efd;
    color: #fff;
}

.btn-secondary {
    background-color: #6c757d;
    color: #fff;
}

.btn-danger {
    background-color: #dc3545;
    color: #fff;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.85rem;
}

/* Avatar */
.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid #ddd;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 0.5rem;
    background-color: #f5f5f5;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 0.75rem;
    color: #999;
}

.avatar-url-display {
    font-size: 0.8rem;
    color: #666;
    word-break: break-all;
}

/* Channels */
.channel-list {
    list-style: none;
    padding: 0;
}

.channel-list li {
    margin-bottom: 0.5rem;
}

.channel-list label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Panel (expandable) */
.panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    cursor: pointer;
    user-select: none;
}

.panel-header h3 {
    margin: 0;
    font-size: 1rem;
}

.expand-icon {
    font-size: 1.1rem;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

/* Status indicator */
.status-indicator {
    font-size: 0.8rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    margin-left: 0.5rem;
}

.status-enabled {
    background-color: #d4edda;
    color: #155724;
}

.status-disabled {
    background-color: #f8d7da;
    color: #721c24;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 1rem;
}

.sessions-table th,
.sessions-table td {
    text-align: left;
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    font-weight: 600;
    background-color: #f8f9fa;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 10px;
    padding: 2rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.modal-dialog p {
    margin-top: 0;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
    font-weight: normal !important;
}

/* Preview area */
.preview-area {
    margin-top: 1.5rem;
    transition: all 0.2s;
}

.preview-area h4 {
    margin-top: 0;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    padding: 0.75rem 1.5rem;
    border-radius: 8px;
    color: #fff;
    font-weight: 500;
    z-index: 2000;
    animation: slide-in 0.2s ease-out;
}

.toast-success {
    background-color: #198754;
}

.toast-error {
    background-color: #dc3545;
}

@keyframes slide-in {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* Utility */
.text-muted {
    color: #6c757d;
    font-size: 0.9rem;
}

